update vm_air_task_t set
task_status = #{execStatus},
medium_status = #{mediaSyncStatus}, reality_time = STR_TO_DATE(#{startTime}, '%Y-%m-%d %H:%i:%s'), fly_Time = #{flyTime}, error_Reason = #{errorReason}, Break_Point_Json = #{breakPointReqJson}, uav_code = #{uavDeviceCode} where plan_task_id = #{taskRecordId}

update vm_air_algorithm_t
set task_status    = #{taskStatus},
    task_record_id = #{taskRecordId}
where task_id = #{taskId}

mapper.select:
select a.device_code, a.alarm_user_id, a.alarm_delay_hour, a.alarm_delay_minute, a.industry_code, a.tenant_id,a.delay_open as delayOpen from `vm_uav_unconnected_alarm` a left join vm_order_uav_devices b on a.device_code = b.device_code and a.tenant_id = b.tenant_id and a.industry_code = b.industry_code where a.delete_flag = 0 and a.unconnected_open = 1 and ord_status in ('0','1','2') and a.device_code in
#{item}
order by a.tenant_id, a.industry_code, a.id

select USER_ID as userId,phonenumber from sys_user where USER_ID in
#{item}
and DEL_FLAG = 0
